fn lower_bound(v: &[i32], x: i32) -> usize {
    let (mut lo, mut hi) = (0, v.len());
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if v[mid] < x {
            lo = mid + 1;
        } else {
            {{hi = mid - 1;|hi = mid;}}
        }
    }
    lo
}

